<?php
require_once __DIR__ . '/../config/database.php'; requireAdmin();
$tenants = []; $dbError = null;
try {
    $tenants = db()->query("SELECT t.*, u.unit_number, a.name AS apartment_name, r.status AS reservation_status FROM tenants t LEFT JOIN reservations r ON r.tenant_id = t.id AND r.status <> 'cancelled' LEFT JOIN units u ON u.id = r.unit_id LEFT JOIN apartments a ON a.id = u.apartment_id ORDER BY t.created_at DESC")->fetchAll();
} catch (Throwable $exception) { $dbError = 'Import sql/migrate_add_tenants.sql to load tenants.'; }
$pageTitle = 'Tenants'; $currentAdminPage = 'tenants'; require __DIR__ . '/partials/header.php';
?><section class="admin-page-toolbar"><div><p class="admin-lede">Tenant accounts and the unit connected to each active reservation.</p></div><span class="toolbar-count"><?= count($tenants) ?> tenant accounts</span></section><?php if ($dbError): ?><div class="database-notice" role="status"><strong>Tenant data unavailable.</strong><span><?= e($dbError) ?></span></div><?php endif; ?><div class="admin-panel admin-list-panel"><div class="admin-table-wrap"><table class="admin-table admin-table-wide"><thead><tr><th>Tenant</th><th>Contact</th><th>Residence</th><th>Account created</th></tr></thead><tbody><?php foreach ($tenants as $tenant): ?><tr><td><strong><?= e($tenant['full_name']) ?></strong><small>Tenant #<?= (int)$tenant['id'] ?></small></td><td><?= e($tenant['email']) ?><small><?= e($tenant['phone']) ?></small></td><td><?php if ($tenant['unit_number']): ?><strong>Unit <?= e($tenant['unit_number']) ?></strong><small><?= e($tenant['apartment_name']) ?> · <?= e(str_replace('_', ' ', $tenant['reservation_status'])) ?></small><?php else: ?><span class="unit-note">No unit assigned</span><?php endif; ?></td><td><?= e(date('M j, Y', strtotime($tenant['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require __DIR__ . '/partials/footer.php'; ?>
